#pragma once

#include <QList>
#include <QMetaObject>
#include <QString>
#include <memory>
#include <type_traits>

#include "Nebula/Component/Component.h"
#include "Nebula/Component/ComponentInfo.h"
#include "Nebula/Plugin/IPlugin.h"

namespace Nebula
{

// Base of P, the class of every plugin, <NAME> in <NAME>.h, generated by nebula_add_plugin: the factory of its
// components, which register in it with NEBULA_REGISTER_COMPONENT. It does not know what they are made of: a component
// creates its own objects when it is constructed.
template <typename P> class Plugin : public IPlugin
{
  public:
    Plugin(const Plugin&) = delete;
    Plugin& operator=(const Plugin&) = delete;

    // Registers the component T; see NEBULA_REGISTER_COMPONENT.
    template <typename T> static bool add()
    {
        checkPluginClass<T>();
        checkComponent<T>();
        registered().append(ComponentType{.metaObject = &T::staticMetaObject, .builder = &make<T>});
        return true;
    }

    [[nodiscard]] QList<const QMetaObject*> components() const override
    {
        QList<const QMetaObject*> components;
        components.reserve(registered().size());
        for(const ComponentType& componentType : registered())
        {
            components.append(componentType.metaObject);
        }
        return components;
    }

    [[nodiscard]] std::unique_ptr<Component> create(const QString& name) const override
    {
        for(const ComponentType& componentType : registered())
        {
            if(componentName(*componentType.metaObject) == name)
            {
                return componentType.builder();
            }
        }
        return nullptr;
    }

  protected:
    Plugin() = default;

  private:
    using Builder = std::unique_ptr<Component> (*)();

    struct ComponentType
    {
        const QMetaObject* metaObject = nullptr;
        Builder builder = nullptr;
    };

    // What create() instantiates rather than T: a component created otherwise would release its interfaces once its
    // own members are destroyed.
    template <typename T> class Instance final : public T
    {
      public:
        // Before the destructor of T: what the component provides and consumes ends while it is still whole.
        ~Instance() override
        {
            this->releaseInterfaces();
        }
    };

    // Does not compile when P is not a plugin class T can be registered in.
    template <typename T> static void checkPluginClass()
    {
        static_assert(std::is_base_of_v<Plugin, P>, "A component is registered in a class deriving from Nebula::Plugin");
        // Never called: what it would create would be missing without a word.
        static_assert(
            !requires(P& plugin, T& component) { plugin.build(component); },
            "build(<component>&) is no longer called: a component creates its objects in its constructor");
    }

    // Does not compile when T is not a component its plugin can create.
    template <typename T> static void checkComponent()
    {
        static_assert(std::is_base_of_v<Component, T>, "A component derives from Nebula::Component");
        // The check qobject_cast makes: without Q_OBJECT, T would be registered under the name of its base class.
        static_assert(QtPrivate::HasQ_OBJECT_Macro<T>::Value, "A component declares Q_OBJECT");
        static_assert(!std::is_final_v<T>, "A component cannot be final: Plugin derives from it");
        static_assert(!std::is_abstract_v<Instance<T>>, "A component implements every pure virtual function");
        static_assert(std::is_default_constructible_v<Instance<T>>, "A component needs a default constructor");
    }

    template <typename T> static std::unique_ptr<Component> make()
    {
        return std::make_unique<Instance<T>>();
    }

    // The components registered in P, from the time its plugin loads, before P is instantiated.
    static QList<ComponentType>& registered()
    {
        static QList<ComponentType> componentTypes;
        return componentTypes;
    }
};

} // namespace Nebula

// Kept to tell a plugin written for 1.0.0 what to remove, rather than a bare unknown name: its class is generated.
#define NEBULA_PLUGIN(Class)                                                                                           \
    static_assert(false, "NEBULA_PLUGIN is no longer used: nebula_add_plugin generates the plugin class in <NAME>.h, "  \
                         "remove its header and its source file")

// Registers Class, a component, in PluginClass, the class of its plugin: <NAME> in <NAME>.h, generated by
// nebula_add_plugin. Used once per component, in a source file:
// #include "ExamplePlugin.h"
// NEBULA_REGISTER_COMPONENT(ExamplePlugin, Greeter);
// Registering can only throw when memory runs out, which ends the program while a plugin loads anyway.
// NOLINTBEGIN(bugprone-throwing-static-initialization)
#define NEBULA_REGISTER_COMPONENT(PluginClass, Class)                                                                  \
    [[maybe_unused]] static const bool NEBULA_DETAIL_CONCAT(nebulaRegistered, __LINE__) =                              \
        Nebula::Plugin<PluginClass>::add<Class>()
// NOLINTEND(bugprone-throwing-static-initialization)
#define NEBULA_DETAIL_CONCAT(first, second) NEBULA_DETAIL_CONCAT_IMPL(first, second)
#define NEBULA_DETAIL_CONCAT_IMPL(first, second) first##second
